export const SOURCE_COMMIT = 'f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5';
export const FREE_EXERCISES = [{"name":"Single-Arm Cable Lateral Raises","sourceId":"Standing_Low-Pulley_Deltoid_Raise","sourceName":"Standing Low-Pulley Deltoid Raise","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms"],"instructions":["Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.","Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.","Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.","Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"images":["Standing_Low-Pulley_Deltoid_Raise/0.jpg","Standing_Low-Pulley_Deltoid_Raise/1.jpg"]},{"name":"Smith Machine Shoulder Press","sourceId":"Smith_Machine_Overhead_Shoulder_Press","sourceName":"Smith Machine Overhead Shoulder Press","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.","Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.","Slowly begin to lower the barbell until it is level with your chin while inhaling.","Then lift the barbell back to the starting position using your shoulders while exhaling.","Repeat for the recommended amount of repetitions."],"images":["Smith_Machine_Overhead_Shoulder_Press/0.jpg","Smith_Machine_Overhead_Shoulder_Press/1.jpg"]},{"name":"Smith Machine Incline Bench Press","sourceId":"Smith_Machine_Incline_Bench_Press","sourceName":"Smith Machine Incline Bench Press","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"images":["Smith_Machine_Incline_Bench_Press/0.jpg","Smith_Machine_Incline_Bench_Press/1.jpg"]},{"name":"Chest Press Machine","sourceId":"Machine_Bench_Press","sourceName":"Machine Bench Press","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Sit down on the Chest Press Machine and select the weight.","Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.","Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.","Now bring the handles back towards you as you breathe in.","Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.","Repeat for the recommended amount of reps.","When finished step on the lever again and slowly get the handles back to their original place."],"images":["Machine_Bench_Press/0.jpg","Machine_Bench_Press/1.jpg"]},{"name":"Preacher Curl","sourceId":"Preacher_Curl","sourceName":"Preacher Curl","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.","With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.","Repeat for the recommended amount of repetitions."],"images":["Preacher_Curl/0.jpg","Preacher_Curl/1.jpg"]},{"name":"Reverse Cable Bicep Curls","sourceId":"Reverse_Cable_Curl","sourceName":"Reverse Cable Curl","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"images":["Reverse_Cable_Curl/0.jpg","Reverse_Cable_Curl/1.jpg"]},{"name":"JM Press","sourceId":"JM_Press","sourceName":"JM Press","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.","Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.","As you exhale, press the bar back up by using the triceps to perform a close grip bench press.","Now go back to the starting position and start over.","Repeat for the recommended amount of repetitions."],"images":["JM_Press/0.jpg","JM_Press/1.jpg"]},{"name":"Leg Press","sourceId":"Leg_Press","sourceName":"Leg Press","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"images":["Leg_Press/0.jpg","Leg_Press/1.jpg"]},{"name":"Seated Leg Curl","sourceId":"Seated_Leg_Curl","sourceName":"Seated Leg Curl","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"images":["Seated_Leg_Curl/0.jpg","Seated_Leg_Curl/1.jpg"]},{"name":"Leg Extension","sourceId":"Leg_Extensions","sourceName":"Leg Extensions","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."],"images":["Leg_Extensions/0.jpg","Leg_Extensions/1.jpg"]},{"name":"Hip Abduction","sourceId":"Thigh_Abductor","sourceName":"Thigh Abductor","equipment":"machine","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"instructions":["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"images":["Thigh_Abductor/0.jpg","Thigh_Abductor/1.jpg"]},{"name":"Hip Adduction","sourceId":"Thigh_Adductor","sourceName":"Thigh Adductor","equipment":"machine","primaryMuscles":["adductors"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them towards each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"images":["Thigh_Adductor/0.jpg","Thigh_Adductor/1.jpg"]},{"name":"Standing Calf Raise","sourceId":"Standing_Calf_Raises","sourceName":"Standing Calf Raises","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"images":["Standing_Calf_Raises/0.jpg","Standing_Calf_Raises/1.jpg"]},{"name":"Leg Press Calf Raise","sourceId":"Calf_Press_On_The_Leg_Press_Machine","sourceName":"Calf Press On The Leg Press Machine","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"images":["Calf_Press_On_The_Leg_Press_Machine/0.jpg","Calf_Press_On_The_Leg_Press_Machine/1.jpg"]},{"name":"Abdominal Crunch Machine","sourceId":"Ab_Crunch_Machine","sourceName":"Ab Crunch Machine","equipment":"machine","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."],"images":["Ab_Crunch_Machine/0.jpg","Ab_Crunch_Machine/1.jpg"]},{"name":"Barbell Curl","sourceId":"Barbell_Curl","sourceName":"Barbell Curl","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"images":["Barbell_Curl/0.jpg","Barbell_Curl/1.jpg"]},{"name":"Cable Preacher Curl","sourceId":"Cable_Preacher_Curl","sourceName":"Cable Preacher Curl","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Place a preacher bench about 2 feet in front of a pulley machine.","Attach a straight bar to the low pulley.","Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.","Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.","Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.","Now slowly lower the weight to the starting position.","Repeat for the recommended amount of repetitions."],"images":["Cable_Preacher_Curl/0.jpg","Cable_Preacher_Curl/1.jpg"]},{"name":"Machine Preacher Curls","sourceId":"Machine_Preacher_Curls","sourceName":"Machine Preacher Curls","equipment":"machine","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Sit down on the Preacher Curl Machine and select the weight.","Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.","Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"images":["Machine_Preacher_Curls/0.jpg","Machine_Preacher_Curls/1.jpg"]},{"name":"Preacher Hammer Dumbbell Curl","sourceId":"Preacher_Hammer_Dumbbell_Curl","sourceName":"Preacher Hammer Dumbbell Curl","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).","As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."],"images":["Preacher_Hammer_Dumbbell_Curl/0.jpg","Preacher_Hammer_Dumbbell_Curl/1.jpg"]},{"name":"Cross Body Hammer Curl","sourceId":"Cross_Body_Hammer_Curl","sourceName":"Cross Body Hammer Curl","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.","While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."],"images":["Cross_Body_Hammer_Curl/0.jpg","Cross_Body_Hammer_Curl/1.jpg"]},{"name":"Incline Hammer Curls","sourceId":"Incline_Hammer_Curls","sourceName":"Incline Hammer Curls","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.","Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.","Continue to the top of the movement and pause, then slowly return to the start position."],"images":["Incline_Hammer_Curls/0.jpg","Incline_Hammer_Curls/1.jpg"]},{"name":"Seated Dumbbell Curl","sourceId":"Seated_Dumbbell_Curl","sourceName":"Seated Dumbbell Curl","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","Rotate the palms of the hands so that they are facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.","Repeat for the recommended amount of repetitions."],"images":["Seated_Dumbbell_Curl/0.jpg","Seated_Dumbbell_Curl/1.jpg"]},{"name":"High Cable Curls","sourceId":"High_Cable_Curls","sourceName":"High Cable Curls","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.","Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.","Slowly bring back the arms to the starting position.","Repeat for the recommended amount of repetitions."],"images":["High_Cable_Curls/0.jpg","High_Cable_Curls/1.jpg"]},{"name":"Overhead Cable Curl","sourceId":"Overhead_Cable_Curl","sourceName":"Overhead Cable Curl","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.","Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.","Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.","While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.","While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.","Repeat for the recommended amount of repetitions prescribed in your program."],"images":["Overhead_Cable_Curl/0.jpg","Overhead_Cable_Curl/1.jpg"]},{"name":"Lying Cable Curl","sourceId":"Lying_Cable_Curl","sourceName":"Lying Cable Curl","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.","Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.","With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.","While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.","After a second squeeze at the top of the movement, slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"images":["Lying_Cable_Curl/0.jpg","Lying_Cable_Curl/1.jpg"]},{"name":"Reverse Barbell Preacher Curls","sourceId":"Reverse_Barbell_Preacher_Curls","sourceName":"Reverse Barbell Preacher Curls","equipment":"e-z curl bar","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Grab an EZ-bar using a shoulder width and palms down (pronated) grip.","Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.","As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.","As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.","Repeat for the recommended amount of repetitions."],"images":["Reverse_Barbell_Preacher_Curls/0.jpg","Reverse_Barbell_Preacher_Curls/1.jpg"]},{"name":"Zottman Preacher Curl","sourceId":"Zottman_Preacher_Curl","sourceName":"Zottman Preacher Curl","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.","As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.","Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.","As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.","Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.","Repeat for the recommended amount of repetitions."],"images":["Zottman_Preacher_Curl/0.jpg","Zottman_Preacher_Curl/1.jpg"]},{"name":"Finger Curls","sourceId":"Finger_Curls","sourceName":"Finger Curls","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.","Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.","Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top."],"images":["Finger_Curls/0.jpg","Finger_Curls/1.jpg"]},{"name":"Dumbbell Lying Pronation","sourceId":"Dumbbell_Lying_Pronation","sourceName":"Dumbbell Lying Pronation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"images":["Dumbbell_Lying_Pronation/0.jpg","Dumbbell_Lying_Pronation/1.jpg"]},{"name":"Dumbbell Lying Supination","sourceId":"Dumbbell_Lying_Supination","sourceName":"Dumbbell Lying Supination","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"images":["Dumbbell_Lying_Supination/0.jpg","Dumbbell_Lying_Supination/1.jpg"]},{"name":"Cable Chest Press","sourceId":"Cable_Chest_Press","sourceName":"Cable Chest Press","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to th starting position, keeping tension on the cables.","You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands."],"images":["Cable_Chest_Press/0.jpg","Cable_Chest_Press/1.jpg"]},{"name":"Incline Cable Chest Press","sourceId":"Incline_Cable_Chest_Press","sourceName":"Incline Cable Chest Press","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to the starting position, keeping tension on the cables."],"images":["Incline_Cable_Chest_Press/0.jpg","Incline_Cable_Chest_Press/1.jpg"]},{"name":"Flat Bench Cable Flyes","sourceId":"Flat_Bench_Cable_Flyes","sourceName":"Flat Bench Cable Flyes","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.","Lay flat on the bench and keep your feet on the ground.","Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.","Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.","Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.","Slowly come back to the starting position.","Repeat for the recommended amount of repetitions."],"images":["Flat_Bench_Cable_Flyes/0.jpg","Flat_Bench_Cable_Flyes/1.jpg"]},{"name":"Incline Cable Flye","sourceId":"Incline_Cable_Flye","sourceName":"Incline Cable Flye","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).","Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.","With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.","With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.","Repeat the movement for the prescribed amount of repetitions."],"images":["Incline_Cable_Flye/0.jpg","Incline_Cable_Flye/1.jpg"]},{"name":"Dumbbell Bench Press with Neutral Grip","sourceId":"Dumbbell_Bench_Press_with_Neutral_Grip","sourceName":"Dumbbell Bench Press with Neutral Grip","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.","Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.","Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.","Pause, then extend the elbow and return to the starting position."],"images":["Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg","Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg"]},{"name":"Close-Grip Dumbbell Press","sourceId":"Close-Grip_Dumbbell_Press","sourceName":"Close-Grip Dumbbell Press","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.","Grasp the dumbbell with both hands and hold it straight over your chest at arm's length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.","Initiate the movement by lowering the dumbbell to your chest.","Return to the starting position by extending the elbows."],"images":["Close-Grip_Dumbbell_Press/0.jpg","Close-Grip_Dumbbell_Press/1.jpg"]},{"name":"Wide-Grip Barbell Bench Press","sourceId":"Wide-Grip_Barbell_Bench_Press","sourceName":"Wide-Grip Barbell Bench Press","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions."],"images":["Wide-Grip_Barbell_Bench_Press/0.jpg","Wide-Grip_Barbell_Bench_Press/1.jpg"]},{"name":"Barbell Guillotine Bench Press","sourceId":"Barbell_Guillotine_Bench_Press","sourceName":"Barbell Guillotine Bench Press","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"images":["Barbell_Guillotine_Bench_Press/0.jpg","Barbell_Guillotine_Bench_Press/1.jpg"]},{"name":"Board Press","sourceId":"Board_Press","sourceName":"Board Press","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","forearms","lats","shoulders"],"instructions":["Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6's, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.","Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"images":["Board_Press/0.jpg","Board_Press/1.jpg"]},{"name":"Pin Presses","sourceId":"Pin_Presses","sourceName":"Pin Presses","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","forearms","lats","middle back","shoulders"],"instructions":["Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.","The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.","Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.","Return the bar to the pins, pausing before beginning the next repetition."],"images":["Pin_Presses/0.jpg","Pin_Presses/1.jpg"]},{"name":"Cable Lying Triceps Extension","sourceId":"Cable_Lying_Triceps_Extension","sourceName":"Cable Lying Triceps Extension","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.","With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.","Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.","Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.","Hold for a second at the contracted position and repeat for the recommended amount of repetitions."],"images":["Cable_Lying_Triceps_Extension/0.jpg","Cable_Lying_Triceps_Extension/1.jpg"]},{"name":"Cable Incline Triceps Extension","sourceId":"Cable_Incline_Triceps_Extension","sourceName":"Cable Incline Triceps Extension","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.","Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.","Slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"images":["Cable_Incline_Triceps_Extension/0.jpg","Cable_Incline_Triceps_Extension/1.jpg"]},{"name":"Tate Press","sourceId":"Tate_Press","sourceName":"Tate Press","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.","Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.","As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."],"images":["Tate_Press/0.jpg","Tate_Press/1.jpg"]},{"name":"Decline Dumbbell Triceps Extension","sourceId":"Decline_Dumbbell_Triceps_Extension","sourceName":"Decline Dumbbell Triceps Extension","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.","As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.","Lift the dumbbells back to the starting position by contracting the triceps and exhaling.","Repeat for the recommended amount of repetitions."],"images":["Decline_Dumbbell_Triceps_Extension/0.jpg","Decline_Dumbbell_Triceps_Extension/1.jpg"]},{"name":"Incline Barbell Triceps Extension","sourceId":"Incline_Barbell_Triceps_Extension","sourceName":"Incline Barbell Triceps Extension","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"instructions":["Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.","Lie back on an incline bench set at any angle between 45-75-degrees.","Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.","Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.","Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"images":["Incline_Barbell_Triceps_Extension/0.jpg","Incline_Barbell_Triceps_Extension/1.jpg"]},{"name":"Smith Machine Close-Grip Bench Press","sourceId":"Smith_Machine_Close-Grip_Bench_Press","sourceName":"Smith Machine Close-Grip Bench Press","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."],"images":["Smith_Machine_Close-Grip_Bench_Press/0.jpg","Smith_Machine_Close-Grip_Bench_Press/1.jpg"]},{"name":"Weighted Bench Dip","sourceId":"Weighted_Bench_Dip","sourceName":"Weighted Bench Dip","equipment":"other","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.","The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"images":["Weighted_Bench_Dip/0.jpg","Weighted_Bench_Dip/1.jpg"]},{"name":"Cable Internal Rotation","sourceId":"Cable_Internal_Rotation","sourceName":"Cable Internal Rotation","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley's height, you can use a flat bench to sit on instead.","Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.","Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.","Slowly go back to the initial position.","Repeat for the recommended amount of repetitions and then repeat the movement with the next arm."],"images":["Cable_Internal_Rotation/0.jpg","Cable_Internal_Rotation/1.jpg"]},{"name":"Band Pull Apart","sourceId":"Band_Pull_Apart","sourceName":"Band Pull Apart","equipment":"bands","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back","traps"],"instructions":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"images":["Band_Pull_Apart/0.jpg","Band_Pull_Apart/1.jpg"]},{"name":"Cuban Press","sourceId":"Cuban_Press","sourceName":"Cuban Press","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the \"scarecrow\" position. This will be your starting position.","To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.","Now press the dumbbells by extending at the elbows, straightening your arms overhead.","Return to the starting position as you breathe in by reversing the steps.","Repeat for the recommended amount of repetitions."],"images":["Cuban_Press/0.jpg","Cuban_Press/1.jpg"]},{"name":"Dumbbell Scaption","sourceId":"Dumbbell_Scaption","sourceName":"Dumbbell Scaption","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.","Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.","Continue until your arms are parallel to the ground, and then return to the starting position."],"images":["Dumbbell_Scaption/0.jpg","Dumbbell_Scaption/1.jpg"]},{"name":"Seated Side Lateral Raise","sourceId":"Seated_Side_Lateral_Raise","sourceName":"Seated Side Lateral Raise","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms' length. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"images":["Seated_Side_Lateral_Raise/0.jpg","Seated_Side_Lateral_Raise/1.jpg"]},{"name":"Cable Seated Lateral Raise","sourceId":"Cable_Seated_Lateral_Raise","sourceName":"Cable Seated Lateral Raise","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back","traps"],"instructions":["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.","Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.","Bend forward while keeping your back flat and rest your torso on the thighs.","Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.","While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.","Slowly lower your arms to the starting position as you inhale.","Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."],"images":["Cable_Seated_Lateral_Raise/0.jpg","Cable_Seated_Lateral_Raise/1.jpg"]},{"name":"Dumbbell One-Arm Shoulder Press","sourceId":"Dumbbell_One-Arm_Shoulder_Press","sourceName":"Dumbbell One-Arm Shoulder Press","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.","As you exhale, push the dumbbell up until your arm is fully extended.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch arms."],"images":["Dumbbell_One-Arm_Shoulder_Press/0.jpg","Dumbbell_One-Arm_Shoulder_Press/1.jpg"]},{"name":"Barbell Rear Delt Row","sourceId":"Barbell_Rear_Delt_Row","sourceName":"Barbell Rear Delt Row","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","lats","middle back"],"instructions":["Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.","Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter \"T\". Now you are ready to begin the exercise.","While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.","Slowly go back to the initial position as you breathe in.","Repeat for the recommended amount of repetitions."],"images":["Barbell_Rear_Delt_Row/0.jpg","Barbell_Rear_Delt_Row/1.jpg"]},{"name":"Reverse Grip Bent-Over Rows","sourceId":"Reverse_Grip_Bent-Over_Rows","sourceName":"Reverse Grip Bent-Over Rows","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["Stand erect while holding a barbell with a supinated grip (palms facing up).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"images":["Reverse_Grip_Bent-Over_Rows/0.jpg","Reverse_Grip_Bent-Over_Rows/1.jpg"]},{"name":"Smith Machine Bent Over Row","sourceId":"Smith_Machine_Bent_Over_Row","sourceName":"Smith Machine Bent Over Row","equipment":"machine","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.","Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"images":["Smith_Machine_Bent_Over_Row/0.jpg","Smith_Machine_Bent_Over_Row/1.jpg"]},{"name":"Scapular Pull-Up","sourceId":"Scapular_Pull-Up","sourceName":"Scapular Pull-Up","equipment":null,"primaryMuscles":["traps"],"secondaryMuscles":["lats","middle back"],"instructions":["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."],"images":["Scapular_Pull-Up/0.jpg","Scapular_Pull-Up/1.jpg"]},{"name":"Rope Straight-Arm Pulldown","sourceId":"Rope_Straight-Arm_Pulldown","sourceName":"Rope Straight-Arm Pulldown","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.","Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.","Pause at the bottom of the motion, squeezing your lats.","Return to the starting position without allowing the weight to fully rest on the stack."],"images":["Rope_Straight-Arm_Pulldown/0.jpg","Rope_Straight-Arm_Pulldown/1.jpg"]},{"name":"Leverage Shrug","sourceId":"Leverage_Shrug","sourceName":"Leverage Shrug","equipment":"machine","primaryMuscles":["traps"],"secondaryMuscles":["forearms"],"instructions":["Load the pins to an appropriate weight. Position yourself directly between the handles.","Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.","Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.","Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.","Pause at the top of the motion, and then return the weight to the starting position."],"images":["Leverage_Shrug/0.jpg","Leverage_Shrug/1.jpg"]},{"name":"Dumbbell Shrug","sourceId":"Dumbbell_Shrug","sourceName":"Dumbbell Shrug","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":[],"instructions":["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.","Lower the dumbbells back to the original position.","Repeat for the recommended amount of repetitions."],"images":["Dumbbell_Shrug/0.jpg","Dumbbell_Shrug/1.jpg"]},{"name":"Standing Dumbbell Calf Raise","sourceId":"Standing_Dumbbell_Calf_Raise","sourceName":"Standing Dumbbell Calf Raise","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.","With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.","As you inhale, go back to the starting position by slowly lowering the heels.","Repeat for the recommended amount of times."],"images":["Standing_Dumbbell_Calf_Raise/0.jpg","Standing_Dumbbell_Calf_Raise/1.jpg"]},{"name":"Smith Machine Calf Raise","sourceId":"Smith_Machine_Calf_Raise","sourceName":"Smith Machine Calf Raise","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.","Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.","Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.","Return slowly to the starting position as you breathe in while lowering your heels.","Repeat for the recommended amount of repetitions."],"images":["Smith_Machine_Calf_Raise/0.jpg","Smith_Machine_Calf_Raise/1.jpg"]},{"name":"Standing Barbell Calf Raise","sourceId":"Standing_Barbell_Calf_Raise","sourceName":"Standing Barbell Calf Raise","equipment":"barbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"images":["Standing_Barbell_Calf_Raise/0.jpg","Standing_Barbell_Calf_Raise/1.jpg"]},{"name":"Barbell Hack Squat","sourceId":"Barbell_Hack_Squat","sourceName":"Barbell Hack Squat","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","hamstrings"],"instructions":["Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.","Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.","Repeat for the recommended amount of repetitions."],"images":["Barbell_Hack_Squat/0.jpg","Barbell_Hack_Squat/1.jpg"]},{"name":"Narrow Stance Hack Squats","sourceId":"Narrow_Stance_Hack_Squats","sourceName":"Narrow Stance Hack Squats","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position.","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"images":["Narrow_Stance_Hack_Squats/0.jpg","Narrow_Stance_Hack_Squats/1.jpg"]},{"name":"Bodyweight Squat","sourceId":"Bodyweight_Squat","sourceName":"Bodyweight Squat","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."],"images":["Bodyweight_Squat/0.jpg","Bodyweight_Squat/1.jpg"]},{"name":"Barbell Lunge","sourceId":"Barbell_Lunge","sourceName":"Barbell Lunge","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"images":["Barbell_Lunge/0.jpg","Barbell_Lunge/1.jpg"]},{"name":"Dumbbell Lunges","sourceId":"Dumbbell_Lunges","sourceName":"Dumbbell Lunges","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"images":["Dumbbell_Lunges/0.jpg","Dumbbell_Lunges/1.jpg"]},{"name":"Overhead Squat","sourceId":"Overhead_Squat","sourceName":"Overhead Squat","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings","lower back","shoulders","triceps"],"instructions":["Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.","Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.","Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.","Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.","Now use your feet and legs to help bring the weight back up to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"images":["Overhead_Squat/0.jpg","Overhead_Squat/1.jpg"]},{"name":"Smith Single-Leg Split Squat","sourceId":"Smith_Single-Leg_Split_Squat","sourceName":"Smith Single-Leg Split Squat","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position","Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement."],"images":["Smith_Single-Leg_Split_Squat/0.jpg","Smith_Single-Leg_Split_Squat/1.jpg"]},{"name":"Ball Leg Curl","sourceId":"Ball_Leg_Curl","sourceName":"Ball Leg Curl","equipment":"exercise ball","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes"],"instructions":["Begin on the floor laying on your back with your feet on top of the ball.","Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.","Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.","Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.","After a brief pause, return to the starting position."],"images":["Ball_Leg_Curl/0.jpg","Ball_Leg_Curl/1.jpg"]},{"name":"Platform Hamstring Slides","sourceId":"Platform_Hamstring_Slides","sourceName":"Platform Hamstring Slides","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"instructions":["For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.","Begin the movement by flexing the knee, keeping your other leg straight.","Continue bringing the heel closer to you, sliding it on the floor.","At full knee flexion, reverse the movement to return to the starting position."],"images":["Platform_Hamstring_Slides/0.jpg","Platform_Hamstring_Slides/1.jpg"]},{"name":"Romanian Deadlift from Deficit","sourceId":"Romanian_Deadlift_from_Deficit","sourceName":"Romanian Deadlift from Deficit","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["forearms","glutes","lower back","traps"],"instructions":["Begin standing while holding a bar at arm's length in front of you. You can stand on a raised platform to increase the range of motion.","Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.","Reverse the motion to return to the starting position."],"images":["Romanian_Deadlift_from_Deficit/0.jpg","Romanian_Deadlift_from_Deficit/1.jpg"]},{"name":"Single Leg Glute Bridge","sourceId":"Single_Leg_Glute_Bridge","sourceName":"Single Leg Glute Bridge","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."],"images":["Single_Leg_Glute_Bridge/0.jpg","Single_Leg_Glute_Bridge/1.jpg"]},{"name":"Cable Deadlifts","sourceId":"Cable_Deadlifts","sourceName":"Cable Deadlifts","equipment":"cable","primaryMuscles":["quadriceps"],"secondaryMuscles":["forearms","glutes","hamstrings","lower back"],"instructions":["Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.","To begin, squat down be flexing your hips and knees until you can reach the handles.","After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.","After reaching a full standing position, Return to the starting position and repeat."],"images":["Cable_Deadlifts/0.jpg","Cable_Deadlifts/1.jpg"]},{"name":"Smith Machine Stiff-Legged Deadlift","sourceId":"Smith_Machine_Stiff-Legged_Deadlift","sourceName":"Smith Machine Stiff-Legged Deadlift","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"images":["Smith_Machine_Stiff-Legged_Deadlift/0.jpg","Smith_Machine_Stiff-Legged_Deadlift/1.jpg"]},{"name":"Superman","sourceId":"Superman","sourceName":"Superman","equipment":"body only","primaryMuscles":["lower back"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"images":["Superman/0.jpg","Superman/1.jpg"]},{"name":"Cable Reverse Crunch","sourceId":"Cable_Reverse_Crunch","sourceName":"Cable Reverse Crunch","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.","Sit down with your feet toward the pulley and attach the cable to your ankles.","Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.","With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.","Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.","Repeat the same movement to failure."],"images":["Cable_Reverse_Crunch/0.jpg","Cable_Reverse_Crunch/1.jpg"]},{"name":"Cable Seated Crunch","sourceId":"Cable_Seated_Crunch","sourceName":"Cable Seated Crunch","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Seat on a flat bench with your back facing a high pulley.","Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.","With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.","As you inhale, go back to the initial position slowly.","Repeat for the recommended amount of repetitions."],"images":["Cable_Seated_Crunch/0.jpg","Cable_Seated_Crunch/1.jpg"]},{"name":"Cable Russian Twists","sourceId":"Cable_Russian_Twists","sourceName":"Cable Russian Twists","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect a standard handle attachment, and position the cable to a middle pulley position.","Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.","Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.","Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.","Repeat the same movement to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"images":["Cable_Russian_Twists/0.jpg","Cable_Russian_Twists/1.jpg"]},{"name":"Pallof Press With Rotation","sourceId":"Pallof_Press_With_Rotation","sourceName":"Pallof Press With Rotation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","shoulders","triceps"],"instructions":["Connect a standard handle to a tower, and position the cable to shoulder height.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.","With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.","Facing forward, press the cable away from your chest. You core should be tight and engaged.","Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.","Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.","With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"images":["Pallof_Press_With_Rotation/0.jpg","Pallof_Press_With_Rotation/1.jpg"]},{"name":"Flutter Kicks","sourceId":"Flutter_Kicks","sourceName":"Flutter Kicks","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.","Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.","Start the movement by lifting the left leg higher than the right leg.","Then lower the left leg as you lift the right leg.","Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."],"images":["Flutter_Kicks/0.jpg","Flutter_Kicks/1.jpg"]},{"name":"Scissor Kick","sourceId":"Scissor_Kick","sourceName":"Scissor Kick","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."],"images":["Scissor_Kick/0.jpg","Scissor_Kick/1.jpg"]},{"name":"Sit-Up","sourceId":"Sit-Up","sourceName":"Sit-Up","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.","Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"images":["Sit-Up/0.jpg","Sit-Up/1.jpg"]},{"name":"Decline Crunch","sourceId":"Decline_Crunch","sourceName":"Decline Crunch","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Secure your legs at the end of the decline bench and lie down.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"images":["Decline_Crunch/0.jpg","Decline_Crunch/1.jpg"]},{"name":"Exercise Ball Crunch","sourceId":"Exercise_Ball_Crunch","sourceName":"Exercise Ball Crunch","equipment":"exercise ball","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).","Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.","With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.","As you inhale, go back to the starting position.","Repeat for the recommended amount of repetitions."],"images":["Exercise_Ball_Crunch/0.jpg","Exercise_Ball_Crunch/1.jpg"]},{"name":"Exercise Ball Pull-In","sourceId":"Exercise_Ball_Pull-In","sourceName":"Exercise Ball Pull-In","equipment":"exercise ball","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.","Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.","While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.","Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"images":["Exercise_Ball_Pull-In/0.jpg","Exercise_Ball_Pull-In/1.jpg"]},{"name":"Stomach Vacuum","sourceId":"Stomach_Vacuum","sourceName":"Stomach Vacuum","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.","Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.","One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.","Repeat for the recommended amount of sets."],"images":["Stomach_Vacuum/0.jpg","Stomach_Vacuum/1.jpg"]},{"name":"Kettlebell Halo","sourceId":"Kettlebell_Halo","sourceName":"Kettlebell Halo","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["traps","middle back","abdominals","triceps"],"instructions":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.","Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.","Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.","Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight."],"images":[]},{"name":"Kettlebell Windmill","sourceId":"Kettlebell_Windmill","sourceName":"Kettlebell Windmill","equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","hamstrings","shoulders","triceps"],"instructions":["Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after reaching the ground and reverse the motion back to the starting position."],"images":["Kettlebell_Windmill/0.jpg","Kettlebell_Windmill/1.jpg"]},{"name":"Kettlebell Figure 8","sourceId":"Kettlebell_Figure_8","sourceName":"Kettlebell Figure 8","equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["hamstrings","shoulders"],"instructions":["Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions."],"images":["Kettlebell_Figure_8/0.jpg","Kettlebell_Figure_8/1.jpg"]},{"name":"Kettlebell Thruster","sourceId":"Kettlebell_Thruster","sourceName":"Kettlebell Thruster","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["quadriceps","triceps"],"instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.","Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.","At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.","As you begin the next repetition, return the weights to the shoulders."],"images":["Kettlebell_Thruster/0.jpg","Kettlebell_Thruster/1.jpg"]},{"name":"One-Arm Kettlebell Row","sourceId":"One-Arm_Kettlebell_Row","sourceName":"One-Arm Kettlebell Row","equipment":"kettlebells","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat."],"images":["One-Arm_Kettlebell_Row/0.jpg","One-Arm_Kettlebell_Row/1.jpg"]},{"name":"One-Arm Kettlebell Snatch","sourceId":"One-Arm_Kettlebell_Snatch","sourceName":"One-Arm Kettlebell Snatch","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","glutes","hamstrings","lower back","traps","triceps"],"instructions":["Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.","Look straight ahead and swing the kettlebell back between your legs.","Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead."],"images":["One-Arm_Kettlebell_Snatch/0.jpg","One-Arm_Kettlebell_Snatch/1.jpg"]},{"name":"One-Arm Kettlebell Floor Press","sourceId":"One-Arm_Kettlebell_Floor_Press","sourceName":"One-Arm Kettlebell Floor Press","equipment":"kettlebells","primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"instructions":["Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.","Press the kettlebell straight up toward the ceiling, rotating your wrist.","Lower the kettlebell back to the starting position and repeat."],"images":["One-Arm_Kettlebell_Floor_Press/0.jpg","One-Arm_Kettlebell_Floor_Press/1.jpg"]},{"name":"Two-Arm Kettlebell Row","sourceId":"Two-Arm_Kettlebell_Row","sourceName":"Two-Arm Kettlebell Row","equipment":"kettlebells","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.","Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat."],"images":["Two-Arm_Kettlebell_Row/0.jpg","Two-Arm_Kettlebell_Row/1.jpg"]},{"name":"Power Clean","sourceId":"Power_Clean","sourceName":"Power Clean","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","forearms","glutes","lower back","middle back","quadriceps","shoulders","traps","triceps"],"instructions":["Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.","Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.","Place the bar about 1 inch in front of your shins and over the balls of your feet.","Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.","Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.","Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.","Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.","As the bar raises keep it as close to the shins as possible.","As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.","Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.","Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.","Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.","When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.","As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.","Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.","After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.","Simultaneously, flex the hips and knees into a quarter squat position.","Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.","Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.","Stand up by extending the hips and knees to a fully erect position.","Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.","Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.","Squat down with the elbows fully extended until the bar touches the floor.","Start over at Phase 1 and repeat for the recommended amount of repetitions."],"images":["Power_Clean/0.jpg","Power_Clean/1.jpg"]},{"name":"Hang Clean","sourceId":"Hang_Clean","sourceName":"Hang Clean","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"instructions":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"images":["Hang_Clean/0.jpg","Hang_Clean/1.jpg"]},{"name":"Power Snatch","sourceId":"Power_Snatch","sourceName":"Power Snatch","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back","quadriceps","shoulders","traps","triceps"],"instructions":["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.","Return to a standing position with the weight over head."],"images":["Power_Snatch/0.jpg","Power_Snatch/1.jpg"]},{"name":"Snatch","sourceId":"Snatch","sourceName":"Snatch","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["biceps","glutes","hamstrings","lower back","shoulders","traps","triceps"],"instructions":["Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.","With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.","Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.","As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.","Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.","Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.","Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead."],"images":["Snatch/0.jpg","Snatch/1.jpg"]},{"name":"Clean and Jerk","sourceId":"Clean_and_Jerk","sourceName":"Clean and Jerk","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","glutes","hamstrings","lower back","quadriceps","traps","triceps"],"instructions":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.","The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position."],"images":["Clean_and_Jerk/0.jpg","Clean_and_Jerk/1.jpg"]},{"name":"Rope Climb","sourceId":"Rope_Climb","sourceName":"Rope Climb","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","forearms","middle back","shoulders"],"instructions":["Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.","Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.","Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.","Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.","To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion."],"images":["Rope_Climb/0.jpg","Rope_Climb/1.jpg"]},{"name":"Tire Flip","sourceId":"Tire_Flip","sourceName":"Tire Flip","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","chest","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"instructions":["Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.","To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.","As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary."],"images":["Tire_Flip/0.jpg","Tire_Flip/1.jpg"]},{"name":"Medicine Ball Chest Pass","sourceId":"Medicine_Ball_Chest_Pass","sourceName":"Medicine Ball Chest Pass","equipment":"medicine ball","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.","Begin facing your partner holding the medicine ball at your torso with both hands.","Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.","Your partner should catch the ball, and throw it back to you.","Receive the throw with both hands at chest height."],"images":["Medicine_Ball_Chest_Pass/0.jpg","Medicine_Ball_Chest_Pass/1.jpg"]},{"name":"Rope Overhead Cable Triceps Extension","sourceId":"Cable_Rope_Overhead_Triceps_Extension","sourceName":"Cable Rope Overhead Triceps Extension","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."],"images":["Cable_Rope_Overhead_Triceps_Extension/0.jpg","Cable_Rope_Overhead_Triceps_Extension/1.jpg"]},{"name":"Cable Wrist Flexion","sourceId":"Cable_Wrist_Curl","sourceName":"Cable Wrist Curl","equipment":"cable","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.","Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.","Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"images":["Cable_Wrist_Curl/0.jpg","Cable_Wrist_Curl/1.jpg"]}];
